) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;


DROP TABLE IF EXISTS `rpbcalendar_subscription_settings`;

CREATE TABLE `rpbcalendar_subscription_settings` (
